INSERT INTO concepts (id,slug,topic_id,zh,sort_order,concept_type,usage_note) VALUES (168,'concept-168','help','询问对方是否介意帮忙做某事',168,'pattern','例：Would you mind opening the window?／窓を開けていただけますか。英语 mind 后接动名词；回答 No 表示不介意，日语直接请求更清楚。');
